"""
===================================================================================
OFFLINE RL / CQL DATASET GENERATOR
===================================================================================

IMPORTANT NOTICE & DATASET DOCUMENTATION:
"This dataset is simulated offline behavioral experience generated by SupplyChainEnv
using seeded DemandHistory. It is not real historical human decision data."

Zero database mutations are performed. All simulation steps operate in memory.
===================================================================================
"""

import os
import sys
import random
import numpy as np
from collections import Counter
from typing import Dict, Any, List

sys.path.insert(0, os.path.abspath("."))

from database.db import SessionLocal
from database.models import InventoryRecord, Order
from services.rl_environment import SupplyChainEnv
from stable_baselines3 import PPO

# Set deterministic random seeds for reproducibility
SEED = 42
random.seed(SEED)
np.random.seed(SEED)


def select_reorder_point_action(obs: np.ndarray, rng: np.random.Generator) -> int:
    """Policy A: Suboptimal Reorder-Point Policy with controlled noise.
    
    Observation vector schema:
      obs[0] = starting_inventory
      obs[8] = reorder_point
    """
    starting_inv = obs[0]
    reorder_point = obs[8]

    if starting_inv <= reorder_point:
        # Reorder point reached: 80% ORDER (1), 10% EXPEDITE (2), 10% NOOP (0)
        return int(rng.choice([1, 2, 0], p=[0.80, 0.10, 0.10]))
    else:
        # Inventory above reorder point: 85% NOOP (0), 15% ORDER (1)
        return int(rng.choice([0, 1], p=[0.85, 0.15]))


def select_random_action(rng: np.random.Generator) -> int:
    """Policy B: Random Exploration Policy."""
    return int(rng.choice([0, 1, 2]))


def select_ppo_action(model: PPO, obs: np.ndarray, rng: np.random.Generator) -> int:
    """Policy C: Trained PPO Policy with mild 10% epsilon exploration."""
    if rng.random() < 0.10:
        return int(rng.choice([0, 1, 2]))
    action, _ = model.predict(obs, deterministic=True)
    return int(action)


def generate_dataset(
    target_transitions: int = 15000,
    output_path: str = os.path.join("training", "datasets", "offline_cql_dataset.npz"),
):
    print("==================================================================")
    print("OFFLINE RL / CQL DATASET GENERATOR")
    print("==================================================================\n")

    db = SessionLocal()

    # Record database snapshot to verify 0 DB mutations
    inv_before = [(r.id, r.quantity) for r in db.query(InventoryRecord).all()]
    orders_before = [(o.id, o.status) for o in db.query(Order).all()]
    print(f"Initial DB State: {len(inv_before)} InventoryRecords, {len(orders_before)} Orders.")

    # Load trained PPO model if available
    ppo_model_path = os.path.join("training", "saved_models", "ppo_supply_chain.zip")
    ppo_model = None
    if os.path.exists(ppo_model_path):
        print(f"Loading trained PPO model from '{ppo_model_path}'...")
        ppo_model = PPO.load(ppo_model_path)
    else:
        print("Warning: Trained PPO model not found. Proceeding with Reorder-Point and Random policies.")

    rng = np.random.default_rng(SEED)

    states_list: List[np.ndarray] = []
    actions_list: List[int] = []
    rewards_list: List[float] = []
    next_states_list: List[np.ndarray] = []
    dones_list: List[bool] = []

    # Products available: 1 through 20
    num_products = 20
    episode_count = 0
    policy_counts = Counter()

    print(f"Generating transitions targeting ~{target_transitions} tuples...\n")

    while len(states_list) < target_transitions:
        product_id = (episode_count % num_products) + 1
        initial_inv = int(rng.integers(10, 100))
        max_steps = 30  # 30-day episode horizon
        fixed_order_qty = 50

        env = SupplyChainEnv(
            db=db,
            product_id=product_id,
            initial_inventory=initial_inv,
            max_steps=max_steps,
            fixed_order_quantity=fixed_order_qty,
        )

        obs, info = env.reset(seed=int(rng.integers(0, 1000000)))

        # Assign policy type for this episode:
        # 50% Suboptimal Reorder-Point, 30% Random, 20% PPO (or Random if PPO unavailable)
        p_val = rng.random()
        if p_val < 0.50:
            policy_type = "REORDER_POINT"
        elif p_val < 0.80 or ppo_model is None:
            policy_type = "RANDOM"
        else:
            policy_type = "PPO"

        policy_counts[policy_type] += 1

        done = False
        while not done and len(states_list) < target_transitions:
            if policy_type == "REORDER_POINT":
                action = select_reorder_point_action(obs, rng)
            elif policy_type == "RANDOM":
                action = select_random_action(rng)
            else:
                action = select_ppo_action(ppo_model, obs, rng)

            next_obs, reward, terminated, truncated, step_info = env.step(action)
            done = terminated or truncated

            states_list.append(obs.copy())
            actions_list.append(action)
            rewards_list.append(float(reward))
            next_states_list.append(next_obs.copy())
            dones_list.append(done)

            obs = next_obs

        episode_count += 1

    db.close()

    # -------------------------------------------------------------
    # CONVERT TO NUMPY ARRAYS & VALIDATE SCHEMA
    # -------------------------------------------------------------
    states = np.array(states_list, dtype=np.float32)
    actions = np.array(actions_list, dtype=np.int64)
    rewards = np.array(rewards_list, dtype=np.float32)
    next_states = np.array(next_states_list, dtype=np.float32)
    dones = np.array(dones_list, dtype=bool)

    N = len(states)
    print("==================================================================")
    print("DATASET SCHEMA & INTEGRITY VALIDATION")
    print("==================================================================")

    assert states.shape == (N, 9), f"states shape must be ({N}, 9), got {states.shape}"
    assert next_states.shape == (N, 9), f"next_states shape must be ({N}, 9), got {next_states.shape}"
    assert states.dtype == np.float32, f"states dtype must be float32, got {states.dtype}"
    assert next_states.dtype == np.float32, f"next_states dtype must be float32, got {next_states.dtype}"
    assert actions.dtype == np.int64, f"actions dtype must be int64, got {actions.dtype}"
    assert rewards.dtype == np.float32, f"rewards dtype must be float32, got {rewards.dtype}"
    assert dones.dtype == bool, f"dones dtype must be bool, got {dones.dtype}"

    # Action set validation
    unique_actions = set(np.unique(actions))
    assert unique_actions == {0, 1, 2}, f"Actions must contain all 3 actions {{0, 1, 2}}, got {unique_actions}"

    # Non-null & Finite validation
    assert np.all(np.isfinite(states)), "states contain NaN or Inf values!"
    assert np.all(np.isfinite(next_states)), "next_states contain NaN or Inf values!"
    assert np.all(np.isfinite(rewards)), "rewards contain NaN or Inf values!"

    # Database isolation validation
    db_check = SessionLocal()
    inv_after = [(r.id, r.quantity) for r in db_check.query(InventoryRecord).all()]
    orders_after = [(o.id, o.status) for o in db_check.query(Order).all()]
    db_check.close()
    assert inv_before == inv_after, "ERROR: InventoryRecord table was mutated!"
    assert orders_before == orders_after, "ERROR: Order table was mutated!"
    print("[OK] All validation checks passed (shapes, types, finite values, action set {0,1,2}, 0 DB mutations).\n")

    # -------------------------------------------------------------
    # SAVE DATASET TO NPZ FILE
    # -------------------------------------------------------------
    os.makedirs(os.path.dirname(output_path), exist_ok=True)
    np.savez_compressed(
        output_path,
        states=states,
        actions=actions,
        rewards=rewards,
        next_states=next_states,
        dones=dones,
    )
    print(f"Dataset successfully saved to: '{os.path.abspath(output_path)}'")

    # -------------------------------------------------------------
    # DATASET SUMMARY REPORT
    # -------------------------------------------------------------
    act_counts = Counter(actions)
    print("\n==================================================================")
    print("OFFLINE RL DATASET SUMMARY REPORT")
    print("==================================================================")
    print(f"Total Transitions (N): {N:,}")
    print(f"Total Episodes:        {episode_count}")
    print(f"Unique Products:       {num_products}")
    print(f"States Array Shape:    {states.shape} ({states.dtype})")
    print(f"Next States Shape:     {next_states.shape} ({next_states.dtype})")
    print(f"Rewards Array Shape:   {rewards.shape} ({rewards.dtype})")
    print(f"Actions Array Shape:   {actions.shape} ({actions.dtype})")
    print(f"Dones Array Shape:     {dones.shape} ({dones.dtype})")
    print(f"Terminal States Count: {int(np.sum(dones))}")
    print("\nAction Distribution Breakdown:")
    for a_val in [0, 1, 2]:
        a_name = {0: "NOOP", 1: "ORDER", 2: "EXPEDITE"}[a_val]
        cnt = act_counts[a_val]
        pct = (cnt / N) * 100.0
        print(f"  - Action {a_val} ({a_name:8s}): {cnt:6,d} transitions ({pct:5.2f}%)")

    print("\nBehavioral Policy Rollout Distribution:")
    for p_name, p_cnt in policy_counts.items():
        print(f"  - {p_name:15s}: {p_cnt:4d} episodes ({(p_cnt/episode_count)*100:.1f}%)")

    print("\nDaily Reward Statistics ($):")
    print(f"  - Mean Reward: ${np.mean(rewards):,.2f}")
    print(f"  - Min Reward:  ${np.min(rewards):,.2f}")
    print(f"  - Max Reward:  ${np.max(rewards):,.2f}")
    print(f"  - Std Reward:  ${np.std(rewards):,.2f}")

    print("\nDATABASE ISOLATION: 100% Verified (Zero SQLite mutations).")
    print("==================================================================")


if __name__ == "__main__":
    generate_dataset(target_transitions=15000)
